 if(!$errors){try{$s=$db->prepare('INSERT INTO users(full_name,email,phone_number,password_hash,role) VALUES(?,?,?,?,?)');$s->execute([$n,$email,$phone,password_hash($pw,PASSWORD_DEFAULT),$role]);$_SESSION['uid']=$db->lastInsertId();$_SESSION['name']=$n;$_SESSION['role']=$role;go($role==='landlord'?'index.php?page=dashboard':'index.php?page=browse');}catch(PDOException $e){$errors[]='That email is already registered.';}}
}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();$s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=$u['user_id'];$_SESSION['name']=$u['full_name'];$_SESSION['role']=$u['role'];go($u['role']==='landlord'?'index.php?page=dashboard':'index.php?page=browse');}$errors[]='Email or password is incorrect.';}
if($page==='create'&&$_SERVER['REQUEST_METHOD']==='POST'){
 need_role('landlord');check_token();try{
 $db->beginTransaction();$s=$db->prepare('INSERT INTO properties(landlord_id,property_title,description,county,town,neighbourhood,property_type,bedrooms,bathrooms,monthly_rent,deposit,availability_status,availability_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');
 $s->execute([$_SESSION['uid'],trim($_POST['title']),trim($_POST['description']),trim($_POST['county']),trim($_POST['town']),trim($_POST['area']),$_POST['type'],(int)$_POST['beds'],(int)$_POST['baths'],(float)$_POST['rent'],($_POST['deposit']??'')!==''?(float)$_POST['deposit']:null,$_POST['status'],($_POST['date']??'')?:null]);
