 $im=$db->prepare('INSERT INTO property_images(property_id,image_url) VALUES(?,?)');foreach($imgs as $v)$im->execute([$id,$v]);
 $am=$db->prepare('INSERT IGNORE INTO property_amenities(property_id,amenity_id) VALUES(?,?)');foreach($_POST['amenities']??[] as $a)$am->execute([$id,(int)$a]);
 $db->commit();flash('Property published successfully.');go('index.php?page=dashboard');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$errors[]=$e->getMessage();}
}
if($page==='edit'&&$_SERVER['REQUEST_METHOD']==='POST'){
