 try{$s=$db->prepare('UPDATE properties SET property_title=?,description=?,county=?,town=?,neighbourhood=?,property_type=?,bedrooms=?,bathrooms=?,monthly_rent=?,deposit=?,availability_status=?,availability_date=? WHERE property_id=? AND landlord_id=?');$s->execute([trim($_POST['title']),trim($_POST['description']),trim($_POST['county']),trim($_POST['town']),trim($_POST['area']),$_POST['type'],(int)$_POST['beds'],(int)$_POST['baths'],(float)$_POST['rent'],($_POST['deposit']??'')!==''?(float)$_POST['deposit']:null,$_POST['status'],($_POST['date']??'')?:null,$id,$_SESSION['uid']]);$imgs=upload_images($_FILES['images']??[]);$im=$db->prepare('INSERT INTO property_images(property_id,image_url) VALUES(?,?)');foreach($imgs as $v)$im->execute([$id,$v]);$db->prepare('DELETE FROM property_amenities WHERE property_id=?')->execute([$id]);$am=$db->prepare('INSERT IGNORE INTO property_amenities(property_id,amenity_id) VALUES(?,?)');foreach($_POST['amenities']??[] as $a)$am->execute([$id,(int)$a]);flash('Property updated.');go('index.php?page=dashboard');}catch(Throwable $e){$errors[]=$e->getMessage();}
}
if($page==='delete'&&$_SERVER['REQUEST_METHOD']==='POST'){need_role('landlord');check_token();$id=(int)$_POST['id'];$q=$db->prepare('SELECT image_url FROM property_images WHERE property_id=? AND property_id IN(SELECT property_id FROM properties WHERE landlord_id=?)');$q->execute([$id,$_SESSION['uid']]);$imgs=$q->fetchAll(PDO::FETCH_COLUMN);$d=$db->prepare('DELETE FROM properties WHERE property_id=? AND landlord_id=?');$d->execute([$id,$_SESSION['uid']]);if($d->rowCount()){foreach($imgs as $im)if(is_file(UPLOAD_DIR.'/'.$im))unlink(UPLOAD_DIR.'/'.$im);flash('Listing deleted.');}go('index.php?page=dashboard');}
