 $sort=$_GET['sort']??'new';$order=$sort==='low'?'p.monthly_rent ASC':($sort==='high'?'p.monthly_rent DESC':'p.created_at DESC');$s=$db->prepare('SELECT p.* FROM properties p WHERE '.implode(' AND ',$where)." ORDER BY $order");$s->execute($params);$list=$s->fetchAll();
